using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SlateOfPlentyOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/SlateOfPlentyOmenData")]
public class SlateOfPlentyOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.SlateOfPlentyOmenAction = delegate(int exceedPurifyAmount)
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			OmenLogic.ActivateOmen(null, exceedPurifyAmount * ActionValue, null, null);
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.SlateOfPlentyOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), GetOmenConvertedDescriptionBattleAction().RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese());
	}
}
